#include <map>
#include <string>

int main() {
    std::map<int, std::string> m;
    m[10] = "Old Value";
    auto it = m.find(10);

    // 1. Value modification is allowed:
    it->second = "New Value";

    // 2. Key modification is disallowed (it->first is const):
    // it->first = 20; // ERROR: assignment of read-only member

    // 3. Correct key modification (Erase-Insert):
    std::string val = it->second;
    m.erase(it);
    m.insert({20, val});
}
